function normalizeWord(s){return String(s).normalize("NFKC").trim().replace(/\s+/g," ").toLocaleLowerCase()}
function addDraft(entry){const key=normalizeWord(entry.answer);if($("dedupeToggle").checked&&drafts.some(d=>normalizeWord(d.answer)===key))return false;drafts.push(entry);return true}

const TTS_LANGS={en:"en-GB",nl:"nl-NL",fr:"fr-FR",es:"es-ES"};
let availableTTSVoices=[];
function selectedTTSLanguage(){return $("ttsLanguage").value||"en-GB"}
function matchingTTSVoices(locale){const base=locale.split("-")[0].toLowerCase();return availableTTSVoices.filter(v=>String(v.lang||"").toLowerCase().startsWith(base+"-")||String(v.lang||"").toLowerCase()===base).sort((a,b)=>{const ae=a.lang.toLowerCase()===locale.toLowerCase()?0:1,be=b.lang.toLowerCase()===locale.toLowerCase()?0:1;return ae-be||a.name.localeCompare(b.name)})}
function refreshTTSVoices(){
 if(!("speechSynthesis" in window))return;
 availableTTSVoices=window.speechSynthesis.getVoices()||[];
 const locale=selectedTTSLanguage(),select=$("ttsVoiceSelect"),voices=matchingTTSVoices(locale),previous=select.value;
 select.innerHTML="";
 if(!voices.length){const o=document.createElement("option");o.value="";o.textContent=tr("ttsNoVoiceOption");select.appendChild(o);select.disabled=true;return}
 select.disabled=false;
 voices.forEach(v=>{const o=document.createElement("option");o.value=v.voiceURI;o.textContent=v.name+" ("+v.lang+")";select.appendChild(o)});
 if(voices.some(v=>v.voiceURI===previous))select.value=previous;
 else {const preferred=voices.find(v=>v.lang.toLowerCase()===locale.toLowerCase())||voices[0];select.value=preferred.voiceURI}
}
function getSelectedTTSVoice(locale=selectedTTSLanguage()){
 const uri=$("ttsVoiceSelect").value;
 return matchingTTSVoices(locale).find(v=>v.voiceURI===uri)||null;
}
$("ttsLanguage").onchange=refreshTTSVoices;
if("speechSynthesis" in window){window.speechSynthesis.onvoiceschanged=refreshTTSVoices;refreshTTSVoices();setTimeout(refreshTTSVoices,500)}
$("addBulkBtn").onclick=()=>{const words=$("bulkWords").value.split(/\r?\n/).map(s=>s.trim()).filter(Boolean);if(!words.length){toast(tr("bulkEmpty"));return}let added=0,skipped=0;const unique=[];for(const word of words){if($("dedupeToggle").checked&&unique.some(x=>normalizeWord(x)===normalizeWord(word))){skipped++;continue}unique.push(word)}if($("bulkMode").value==="tts"){const locale=selectedTTSLanguage(),voice=getSelectedTTSVoice(locale);if(!voice){toast(tr("ttsVoiceUnavailable"));return}for(const answer of unique){if(addDraft({answer,tts:true,lang:locale,voiceURI:voice.voiceURI,voiceName:voice.name}))added++;else skipped++}renderDrafts();$("bulkWords").value="";if(skipped)toast(tr("duplicatesRemoved"));else toast(added+" "+tr("words").toLowerCase());return}recordQueue=unique.filter(w=>!($("dedupeToggle").checked&&drafts.some(d=>normalizeWord(d.answer)===normalizeWord(w))));skipped=unique.length-recordQueue.length;if(!recordQueue.length){toast(tr("duplicatesRemoved"));return}$("bulkWords").value="";$("answer").value=recordQueue.shift();$("clipStatus").textContent=tr("speakStop");$("answer").focus();toast(skipped?tr("duplicatesRemoved"):tr("recordAdded"))};
function speakEntry(entry){if(entry.tts){if(!("speechSynthesis" in window)){toast(tr("ttsUnavailable"));return}const locale=entry.lang||TTS_LANGS[language]||"en-GB";const voices=matchingTTSVoices(locale);if(!voices.length){toast(tr("ttsVoiceUnavailable"));return}window.speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(entry.answer);u.lang=locale;const chosen=voices.find(v=>entry.voiceURI&&v.voiceURI===entry.voiceURI)||voices.find(v=>v.lang.toLowerCase()===locale.toLowerCase())||voices[0];u.voice=chosen;window.speechSynthesis.speak(u);return}const audio=$("practiceAudio");audio.src=entry.audio;audio.currentTime=0;audio.play().catch(()=>toast(tr("playFailed")))}
function cancelAuto(){if(autoTimer){clearTimeout(autoTimer);autoTimer=null}if(autoAdvanceTimer){clearTimeout(autoAdvanceTimer);autoAdvanceTimer=null}autoAdvanceTriggered=false;$("autoCountdown").textContent=""}
function scheduleAutoNext(){cancelAuto();if(!$('autoSpeakToggle').checked||!answered)return;$("autoCountdown").textContent=tr("autoCountdown");autoTimer=setTimeout(()=>{autoTimer=null;if(!$('autoSpeakToggle').checked)return;if(activeIndex<activeSet.entries.length-1){activeIndex++;showQuestion(true);speakEntry(activeSet.entries[activeIndex])}else{toast(tr("complete"));show("library")}},3000)}
