function renderMindmap(){const m=activeMap();if(!m)return;const animateThisRender=mmAnimateOnOpen;mmAnimateOnOpen=false;const group=$("mindmapViewport");group.innerHTML="";const {nodes,edges}=layoutMindmap();const transform=svgEl("g",{transform:`translate(${mmPan.x} ${mmPan.y}) translate(1000 650) scale(${mmScale}) translate(-1000 -650)`});edges.forEach((e,i)=>{const dx=e.to.x-e.from.x,dir=Math.sign(dx)||1;const c1=e.from.x+dx*.48,c2=e.to.x-dx*.48;const path=svgEl("path",{class:"mindmap-connector"+(animateThisRender?" mm-reveal":""),d:`M ${e.from.x} ${e.from.y} C ${c1} ${e.from.y}, ${c2} ${e.to.y}, ${e.to.x} ${e.to.y}`,stroke:e.color});if(animateThisRender){const length=Math.ceil(Math.hypot(dx,e.to.y-e.from.y)*1.15);path.style.setProperty("--mm-line-length",length+"px");path.style.setProperty("--mm-delay",Math.min(i*38,520)+"ms")}transform.append(path)});
 nodes.forEach((item,index)=>{const n=item.node,g=svgEl("g",{class:`mindmap-node${item.main?" main-branch":""}${item.root?" mindmap-root":""}${selectedNodeId===n.id?" selected":""}${animateThisRender?" mm-reveal":""}`,"data-node-id":n.id});if(animateThisRender){g.style.setProperty("--mm-delay",Math.min(90+index*34,760)+"ms");g.style.setProperty("--mm-from-x",(item.x<1000?-18:18)+"px");g.style.setProperty("--mm-from-y",(item.y<650?-10:10)+"px");}if(item.root){const label=n.label||"Central topic",w=Math.max(160,Math.min(320,label.length*14+38));g.append(svgEl("rect",{x:item.x-w/2,y:item.y-34,width:w,height:68,rx:9}));const text=svgEl("text",{x:item.x,y:item.y+8,"text-anchor":"middle"});text.textContent=label;g.append(text)}else{const anchor=item.side<0?"end":"start",tx=item.x+(item.side<0?-10:10),label=n.label||"New branch",boxW=Math.max(82,Math.min(280,label.length*9.2+24)),boxX=item.main?(item.side<0?tx-boxW:tx):Math.min(item.x-5,tx-5),boxY=item.y-22;const hit=svgEl("rect",{class:"node-hit",x:boxX,y:boxY,width:item.main?boxW:Math.max(70,label.length*9+20),height:32,rx:item.main?6:5});if(item.main)hit.setAttribute("style",`--branch-color:${item.color}`);g.append(hit);const text=svgEl("text",{x:item.main?boxX+boxW/2:tx,y:item.y+5,"text-anchor":item.main?"middle":anchor});text.textContent=label;g.append(text);if(n.notes){const dot=svgEl("circle",{cx:item.x,cy:item.y,r:3.2,fill:item.color||item.color||item.node.color||item.color||"#fff"});g.append(dot)}}g.addEventListener("click",e=>{e.stopPropagation();selectMindmapNode(n.id)});g.addEventListener("pointerdown",e=>{if(e.target.closest("text")||e.target.closest("rect")){e.stopPropagation();mmDragNode={id:n.id,startX:e.clientX,startY:e.clientY,offset:{...(n.offset||{})}}}});transform.append(g)});group.append(transform);}
