 return new Promise((resolve,reject)=>{const data=new XMLSerializer().serializeToString(svg),url=URL.createObjectURL(new Blob([data],{type:"image/svg+xml;charset=utf-8"})),img=new Image();img.onload=()=>{const c=document.createElement("canvas");c.width=width;c.height=height;const ctx=c.getContext("2d");ctx.fillStyle="#fff";ctx.fillRect(0,0,width,height);ctx.drawImage(img,0,0,width,height);URL.revokeObjectURL(url);resolve(c)};img.onerror=()=>{URL.revokeObjectURL(url);reject(new Error("Could not render the mindmap"))};img.src=url});
